package com.ailab.system.report.provider;
import com.ailab.system.domain.LabAsset; import com.ailab.system.report.config.*; import com.ailab.system.report.model.*; import com.ailab.system.service.LabAssetRiskPolicy; import java.util.*; import org.springframework.stereotype.Component;
@Component public final class AssetSummaryProvider extends AbstractLabDataSourceProvider { private final LabAssetRiskPolicy riskPolicy=new LabAssetRiskPolicy(); public AssetSummaryProvider(){super(ReportConfigCatalog.ASSET_SUMMARY,new LinkedHashSet<String>(Arrays.asList("id","assetNo","assetName","assetType","assetStage","ownerId","backupOwnerId","criticalFlag","status","backupOwnerStatus","singlePointRisk")));} protected ReportSectionData loadValidated(ReportQueryCriteria c,ReportSectionConfig s){List<Map<String,Object>>r=copyRows(mapper().selectAssets(c));int risk=0;for(Map<String,Object>x:r){LabAsset asset=new LabAsset();asset.setStatus((String)x.get("status"));asset.setAssetStage((String)x.get("assetStage"));asset.setCriticalFlag((String)x.get("criticalFlag"));asset.setBackupOwnerId(longValue(x.get("backupOwnerId")));asset.setBackupOwnerStatus((String)x.get("backupOwnerStatus"));riskPolicy.apply(asset);x.put("singlePointRisk",Boolean.valueOf(asset.isSinglePointRisk()));if(asset.isSinglePointRisk())risk++;}Map<String,Object>z=summaryCount(r);z.put("singlePointRiskCount",risk);return section(c,s,r,z);} private Long longValue(Object v){return v==null?null:Long.valueOf(String.valueOf(v));}}
